@import "@fontsource-variable/manrope";

/* Light: white page, #101010 ink, electric blue #218aff for CTAs and highlighted words,
   #eeeeee card surfaces, 8% ink hairlines, a pale-blue wash (accent) for active cards. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.178 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.178 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.178 0 0);
  --primary: oklch(0.646 0.196 255.5);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.948 0 0);
  --secondary-foreground: oklch(0.178 0 0);
  --muted: oklch(0.948 0 0);
  --muted-foreground: oklch(0.178 0 0 / 60%);
  --accent: oklch(0.955 0.02 255);
  --accent-foreground: oklch(0.178 0 0);
  --destructive: oklch(0.6 0.22 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.178 0 0 / 8%);
  --input: oklch(0.178 0 0 / 15%);
  --ring: oklch(0.646 0.196 255.5);
  --highlight: oklch(0.79 0.12 41);
  --highlight-foreground: oklch(0.178 0 0);
  --glow: oklch(0.72 0.14 252);
  --chart-1: oklch(0.646 0.196 255.5);
  --chart-2: oklch(0.79 0.12 41);
  --chart-3: oklch(0.72 0.14 252);
  --chart-4: oklch(0.178 0 0);
  --chart-5: oklch(0.6 0 0);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.178 0 0);
  --sidebar-primary: oklch(0.646 0.196 255.5);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.948 0 0);
  --sidebar-accent-foreground: oklch(0.178 0 0);
  --sidebar-border: oklch(0.178 0 0 / 8%);
  --sidebar-ring: oklch(0.646 0.196 255.5);

  --typeface-body: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.5rem;
  --page-width: 77.5rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark: the sibling — the original's own dark moments (#101010 cards, white text at 64%),
   #1c1c1c raised panels, the same blue. */
.dark {
  --background: oklch(0.178 0 0);
  --foreground: oklch(0.96 0 0);
  --card: oklch(0.225 0 0);
  --card-foreground: oklch(0.96 0 0);
  --popover: oklch(0.225 0 0);
  --popover-foreground: oklch(0.96 0 0);
  --primary: oklch(0.646 0.196 255.5);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.27 0 0);
  --secondary-foreground: oklch(0.96 0 0);
  --muted: oklch(0.36 0 0);
  --muted-foreground: oklch(1 0 0 / 64%);
  --accent: oklch(0.3 0.04 255);
  --accent-foreground: oklch(0.96 0 0);
  --destructive: oklch(0.68 0.19 22);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.646 0.196 255.5);
  --highlight: oklch(0.79 0.12 41);
  --highlight-foreground: oklch(0.178 0 0);
  --glow: oklch(0.6 0.17 255);
  --chart-1: oklch(0.646 0.196 255.5);
  --chart-2: oklch(0.79 0.12 41);
  --chart-3: oklch(0.72 0.14 252);
  --chart-4: oklch(0.96 0 0);
  --chart-5: oklch(0.6 0 0);
  --sidebar: oklch(0.2 0 0);
  --sidebar-foreground: oklch(0.96 0 0);
  --sidebar-primary: oklch(0.646 0.196 255.5);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.27 0 0);
  --sidebar-accent-foreground: oklch(0.96 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.646 0.196 255.5);
}
